create or replace function public.platform_security_overview() returns jsonb language plpgsql stable security definer set search_path=public,auth as $$ begin if not public.is_platform_admin()then raise exception 'Acesso restrito';end if;return jsonb_build_object('generated_at',now(),'metrics',jsonb_build_object('users',(select count(*)from auth.users),'mfa_enabled',(select count(*)from profiles where coalesce(mfa_enabled,false)),'unconfirmed_email',(select count(*)from auth.users where email_confirmed_at is null),'inactive_90d',(select count(*)from auth.users where last_sign_in_at is null or last_sign_in_at<now()-interval'90 days'),'open_sessions',(select count(*)from auth.sessions),'platform_admins',(select count(*)from platform_admins where ativo),'assisted_access',(select count(*)from support_access_requests where status='approved'and expires_at>now())),'admins',coalesce((select jsonb_agg(jsonb_build_object('user_id',p.user_id,'level',p.nivel,'active',p.ativo,'created_at',p.created_at,'last_sign_in_at',u.last_sign_in_at,'mfa_enabled',coalesce(pr.mfa_enabled,false))order by p.created_at)from platform_admins p join auth.users u on u.id=p.user_id left join profiles pr on pr.id=p.user_id),'[]'::jsonb),'recent_sensitive_actions',coalesce((select jsonb_agg(to_jsonb(x)order by x.timestamp desc)from(select id,user_id,action,collection,record_id,timestamp from audit_log where collection in('platform_restore_requests','support_access','platform_incidents','notification_queue','mercadopago_webhook_logs')order by timestamp desc limit 100)x),'[]'::jsonb));end;$$;
revoke all on function public.platform_security_overview()from public,anon;grant execute on function public.platform_security_overview()to authenticated;
